import{_ as a,o,c as s,a2 as n}from"./chunks/framework.BWuWLRhz.js";const g=JSON.parse('{"title":"Plugins (Gestión)","description":"","frontmatter":{},"headers":[],"relativePath":"es-ES/user-guide/settings/plugins.md","filePath":"es-ES/user-guide/settings/plugins.md","lastUpdated":1788596486000}'),i={name:"es-ES/user-guide/settings/plugins.md"};function r(t,e,l,d,c,u){return o(),s("div",null,[...e[0]||(e[0]=[n('<h1 id="plugins-gestion" tabindex="-1">Plugins (Gestión) <a class="header-anchor" href="#plugins-gestion" aria-label="Permalink to &quot;Plugins (Gestión)&quot;">​</a></h1><p>Lertaro cuenta con una arquitectura modular de extensiones. Tanto los componentes internos como los plugins nativos en C# y el ecosistema de Flow Launcher se gestionan en <strong>Configuración → Plugins</strong>.</p><h2 id="_1-diseno-de-pagina-y-version-del-sdk" tabindex="-1">1. Diseño de página y versión del SDK <a class="header-anchor" href="#_1-diseno-de-pagina-y-version-del-sdk" aria-label="Permalink to &quot;1. Diseño de página y versión del SDK&quot;">​</a></h2><ul><li><strong>Insignia del SDK</strong>: En la esquina superior derecha se muestra la versión cargada de <code>Lertaro.PluginSdk</code>. Al hacer clic se abre la <a href="./../../dev-guide/"><strong>Guía de desarrollo</strong></a>.</li><li><strong>Diseño de doble panel independiente</strong>: La columna izquierda muestra los plugins instalados y la derecha presenta los detalles y el formulario de configuración del plugin seleccionado, con desplazamiento independiente.</li></ul><h2 id="_2-detalles-del-plugin-y-conmutadores-de-componentes" tabindex="-1">2. Detalles del plugin y conmutadores de componentes <a class="header-anchor" href="#_2-detalles-del-plugin-y-conmutadores-de-componentes" aria-label="Permalink to &quot;2. Detalles del plugin y conmutadores de componentes&quot;">​</a></h2><p>Al seleccionar un plugin a la izquierda, el panel derecho muestra su icono, nombre, versión y descripción:</p><h3 id="pestana-detalles-details" tabindex="-1">Pestaña Detalles (Details) <a class="header-anchor" href="#pestana-detalles-details" aria-label="Permalink to &quot;Pestaña Detalles (Details)&quot;">​</a></h3><ul><li><strong>Lista de componentes</strong>: Muestra todos los componentes funcionales registrados (fuentes de búsqueda, proveedores de acciones, accesos rápidos, manejadores de vista previa, etc.).</li><li><strong>Conmutadores individuales</strong>: Cada componente no esencial dispone de una <strong>casilla de activación</strong>; los componentes imprescindibles muestran un icono de candado y no se pueden desactivar.</li><li><strong>Seleccionar / Deseleccionar todo</strong>: Enlace rápido para alternar en bloque todos los elementos de un grupo.</li><li><strong>Descripción emergente</strong>: Pasa el ratón sobre el icono <strong>(!)</strong> de un componente para consultar sus detalles técnicos y activación.</li></ul><h3 id="pestana-configuracion-configure" tabindex="-1">Pestaña Configuración (Configure) <a class="header-anchor" href="#pestana-configuracion-configure" aria-label="Permalink to &quot;Pestaña Configuración (Configure)&quot;">​</a></h3><ul><li><strong>Formularios incrustados</strong>: Las opciones personalizadas del plugin se muestran en el panel derecho sin cuadros de diálogo adicionales (campos de texto, números, selectores, pestañas, etc.).</li><li><strong>Campos de icono</strong>: Los campos de texto con la clave de esquema <code>Icon</code> muestran una vista previa y admiten WPF Path Data. Al pegar un documento SVG/XML completo, sus datos de ruta se extraen y combinan automáticamente; el contenido no válido se borra y se notifica mediante un cuadro de diálogo con el tema de Lertaro.</li><li><strong>Guardado seguro y restauración</strong>: Los cambios se conservan en memoria hasta pulsar <strong>Aceptar</strong>; cambiar de plugin o salir de la página restaura los valores anteriores automáticamente.</li></ul><h3 id="filtros-de-tipo-de-busqueda-de-coreextensions" tabindex="-1">Filtros de tipo de búsqueda de CoreExtensions <a class="header-anchor" href="#filtros-de-tipo-de-busqueda-de-coreextensions" aria-label="Permalink to &quot;Filtros de tipo de búsqueda de CoreExtensions&quot;">​</a></h3><p>En <strong>Configuración → Plugins → CoreExtensions → Configurar → Filtros de búsqueda</strong> puedes controlar los filtros de tipo que aparecen a la izquierda de la ventana de búsqueda completa. Los archivos y las carpetas siempre están disponibles; los filtros de documentos, imágenes y vídeos se pueden desactivar por separado.</p><p>La lista <strong>Filtros personalizados de la barra lateral</strong> añade filtros con un nombre visible, un icono WPF Path Data opcional y una regla con comodines. Los nombres vacíos o las reglas que quedan vacías tras la expansión se ocultan, y un icono vacío usa el icono predeterminado. El nombre solo se muestra y no es una referencia <code>@</code>. Las referencias <code>@</code> solo son válidas en el campo Regla: <code>@palabra-clave</code> expande una palabra clave coincidente de la lista existente <strong>Filtros personalizados</strong>, aunque ese filtro esté deshabilitado. Las referencias se expanden de forma recursiva y los patrones duplicados se eliminan; las referencias desconocidas o cíclicas no producen reglas coincidentes.</p><h2 id="_3-soporte-del-ecosistema-de-plugins-de-flow-launcher" tabindex="-1">3. Soporte del ecosistema de plugins de Flow Launcher <a class="header-anchor" href="#_3-soporte-del-ecosistema-de-plugins-de-flow-launcher" aria-label="Permalink to &quot;3. Soporte del ecosistema de plugins de Flow Launcher&quot;">​</a></h2><p>Además de los plugins nativos de <code>Lertaro.PluginSdk</code>, el módulo integrado <strong>Flow Launcher Bridge</strong> ofrece compatibilidad total con el extenso catálogo de Flow Launcher.</p><h3 id="entornos-aislados-y-multilingues" tabindex="-1">Entornos aislados y multilingües <a class="header-anchor" href="#entornos-aislados-y-multilingues" aria-label="Permalink to &quot;Entornos aislados y multilingües&quot;">​</a></h3><ul><li><strong>Compatibilidad total</strong>: Ejecuta plugins de Flow Launcher escritos en <strong>C# (.NET)</strong>, <strong>Python 3.12</strong>, <strong>Node.js v20 LTS</strong> y binarios ejecutables (<code>.exe</code>).</li><li><strong>Aislamiento sin alterar el sistema</strong>: Los entornos de Python (<code>FlowData\\PythonEmbeded-{arch}</code>) y Node.js (<code>FlowData\\NodeEmbeded-{arch}</code>) se despliegan automáticamente dentro de la carpeta de datos de Lertaro sin modificar la variable PATH de Windows.</li><li><strong>Instalación automática de dependencias</strong>: Al cargar un plugin por primera vez, instala silenciosamente las librerías necesarias mediante <code>requirements.txt</code> (Python pip) o <code>package.json</code> (Node.js npm).</li></ul><h3 id="gestion-desde-la-barra-de-busqueda" tabindex="-1">Gestión desde la barra de búsqueda <a class="header-anchor" href="#gestion-desde-la-barra-de-busqueda" aria-label="Permalink to &quot;Gestión desde la barra de búsqueda&quot;">​</a></h3><p>Gestiona plugins de Flow directamente con comandos en la barra de búsqueda:</p><ul><li><strong><code>flow install &lt;palabra clave&gt;</code></strong>: Busca en el repositorio oficial de Flow.Launcher y descarga, extrae e instala el plugin y sus dependencias en un solo paso.</li><li><strong><code>flow update</code></strong>: Comprueba actualizaciones de los plugins instalados y los actualiza.</li><li><strong><code>flow uninstall &lt;nombre&gt;</code></strong>: Desinstala el plugin y limpia sus carpetas locales.</li><li><strong>Instalación manual</strong>: Puedes colocar carpetas de plugins descargados en <code>&lt;DirectorioUsuario&gt;\\FlowData\\Plugins\\</code>.</li></ul><h3 id="configuracion-palabras-clave-y-vistas-previas-enriquecidas" tabindex="-1">Configuración, palabras clave y vistas previas enriquecidas <a class="header-anchor" href="#configuracion-palabras-clave-y-vistas-previas-enriquecidas" aria-label="Permalink to &quot;Configuración, palabras clave y vistas previas enriquecidas&quot;">​</a></h3><ul><li><strong>Gestión de ActionKeyword</strong>: En <strong>Configuración → Plugins → Flow Launcher Bridge → Configuración</strong>, activa o desactiva plugins individuales y modifica su <strong>ActionKeyword</strong> (almacenado en <code>FlowData\\Settings\\Plugins.json</code>).</li><li><strong>Formularios dinámicos</strong>: Compatible con plantillas YAML/JSON (<code>SettingsTemplate.yaml</code>/<code>.json</code>) y paneles WPF (<code>ISettingProvider</code>), adaptados al tema visual activo y con soporte de traducción.</li><li><strong>Vistas previas interactivas con WebView2</strong>: Muestra paneles ricos (diccionarios MDict, pronósticos del tiempo, depuradores API, capturas web) en la ventana de QuickLook.</li><li><strong>Integración profunda con el anfitrión</strong>: Los plugins de Flow que abren carpetas respetan automáticamente el administrador de archivos de terceros configurado por el anfitrión, los cuadros de mensaje se muestran con el tema visual nativo y los registros internos se integran en el visor de registros de Configuración.</li><li><strong>Listado rápido</strong>: Escribe <code>flow</code> en la barra de búsqueda para ver todos los plugins cargados y sus palabras clave activas; al seleccionar un plugin se abre su grupo de configuración correspondiente.</li></ul><h2 id="_4-selector-de-dispositivos-de-audio" tabindex="-1">4. Selector de dispositivos de audio <a class="header-anchor" href="#_4-selector-de-dispositivos-de-audio" aria-label="Permalink to &quot;4. Selector de dispositivos de audio&quot;">​</a></h2><p>El <strong>Selector de dispositivos de audio</strong> es un plugin nativo exclusivo para Windows. Escribe <code>ad</code> para mostrar los dispositivos activos de salida y entrada, y selecciona uno para convertirlo en el dispositivo multimedia predeterminado correspondiente. También puedes añadir el nombre de un dispositivo después de la palabra clave para filtrar los resultados.</p><p>En su configuración puedes cambiar la palabra clave activadora y elegir si los resultados muestran el nombre descriptivo, el nombre del dispositivo o su descripción. Cambia el punto final predeterminado de salida o entrada, pero no controla el volumen, el silencio ni el enrutamiento de audio por aplicación.</p><h2 id="_5-busqueda-de-contenido" tabindex="-1">5. Búsqueda de contenido <a class="header-anchor" href="#_5-busqueda-de-contenido" aria-label="Permalink to &quot;5. Búsqueda de contenido&quot;">​</a></h2><p>El plugin <strong>Búsqueda de contenido</strong> busca en el texto de los documentos locales configurados. En la pestaña <strong>Configurar</strong> puedes establecer la palabra clave activadora, las carpetas supervisadas, las extensiones indexadas, el límite por archivo, el límite de tamaño del índice y las expresiones regulares para excluir rutas completas. La palabra clave predeterminada es <code>cs</code>; escribe <code>cs plan del proyecto</code> para buscar en el contenido y mostrar archivos coincidentes con fragmentos.</p><p>La configuración también ofrece <strong>Borrar índice</strong> y <strong>Reconstruir índice</strong>. Borrar elimina solo el índice de contenido, mientras que Reconstruir lo elimina y vuelve a analizar todas las carpetas supervisadas. Ninguna de las dos acciones elimina el índice normal de nombres de archivo de Lertaro.</p><h2 id="_6-estado-de-ejecucion-de-plugins" tabindex="-1">6. Estado de ejecución de plugins <a class="header-anchor" href="#_6-estado-de-ejecucion-de-plugins" aria-label="Permalink to &quot;6. Estado de ejecución de plugins&quot;">​</a></h2><p>La pestaña <strong>Estado de ejecución</strong>, dentro de <strong>Configuración → Plugins</strong>, muestra la actividad del anfitrión para los plugins instalados mientras Lertaro está en ejecución. Los valores se agregan por plugin y se actualizan mientras la pestaña está abierta.</p><ul><li><strong>Filtro de plugins</strong>: Usa el cuadro de filtro para buscar de forma difusa por nombre de plugin.</li><li><strong>Columnas ordenables</strong>: Haz clic en un encabezado para alternar entre orden ascendente, descendente y el orden predeterminado de plugins.</li><li><strong>Métricas disponibles</strong>: Número de llamadas, duración media, duración más reciente, duración máxima, asignación administrada y excepciones observadas.</li><li><strong>Alcance de la sesión</strong>: Las estadísticas se acumulan durante el proceso actual de Lertaro y se reinician al volver a iniciar la aplicación. Un cero indica que todavía no se ha registrado una llamada medida. La asignación administrada es la memoria asignada por las llamadas medidas, no el uso total de memoria privada del plugin.</li></ul>',31)])])}const m=a(i,[["render",r]]);export{g as __pageData,m as default};
